/** Property definition utility. */
/** Defines a non-writable, non-configurable, non-enumerable property by default. */
export const defineProp = (ob, key, val, config = {}) => {
    const { writable = false, configurable = false, enumerable = false, } = config;
    Object.defineProperty(ob, key, {
        value: val,
        writable,
        configurable,
        enumerable,
    });
};
